// Lumen Layer Studio service worker: offline use, fast start, and the Android "Share to" target.
// Generated by build-web.py; the version changes whenever index.html changes.
const CACHE = 'lumen-eab7682b3889';
const CORE = ['./', './index.html', './manifest.webmanifest', './pwa/icon-192.png', './pwa/icon-512.png', './pwa/icon-maskable-512.png', './pwa/apple-touch-icon.png'];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(CORE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE && k !== 'lumen-share').map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  // Android share sheet → "Lumen Layer": keep the shared photos, then open the app to import them.
  if (e.request.method === 'POST' && url.pathname.endsWith('/share-target')) {
    e.respondWith((async () => {
      const form = await e.request.formData(), cache = await caches.open('lumen-share');
      for (const k of await cache.keys()) await cache.delete(k);
      let n = 0;
      for (const f of form.getAll('photos')) {
        if (!(f instanceof File)) continue;
        await cache.put(new Request(`./shared/${n++}/${encodeURIComponent(f.name)}`), new Response(f, { headers: { 'Content-Type': f.type || 'application/octet-stream' } }));
      }
      return Response.redirect(new URL(`./?shared=${n}`, self.registration.scope).href, 303);
    })());
    return;
  }
  if (e.request.method !== 'GET') return;
  if (url.origin === location.origin) {
    if (/\.exe$/i.test(url.pathname)) return; // never cache the Windows downloads
    // App files: answer from cache instantly, refresh in the background.
    e.respondWith(caches.open(CACHE).then(async c => {
      const hit = await c.match(e.request, { ignoreSearch: true });
      const net = fetch(e.request).then(r => { if (r.ok) c.put(e.request, r.clone()); return r; }).catch(() => hit);
      return hit || net;
    }));
    return;
  }
  // Fonts and the styling library: keep a copy so the app looks right offline.
  if (/(^|\.)fonts\.(googleapis|gstatic)\.com$|^cdn\.tailwindcss\.com$/.test(url.hostname)) {
    e.respondWith(caches.open(CACHE).then(async c => {
      const hit = await c.match(e.request); if (hit) return hit;
      try { const r = await fetch(e.request); c.put(e.request, r.clone()); return r; } catch (_) { return Response.error(); }
    }));
  }
});
